        RListIter *iter;
        RAnalPlugin *h;
        if (!core || !core->anal || !name) {
                return NULL;
        }
        RAnal *a = core->anal;
        r_list_foreach (a->plugins, iter, h) {
                if (!strcmp (name, h->name)) {
                        return h->esil? "Ae": "A_";
                }
        }
        return "__";
}

